function uYd(){uYd=HUc;qYd=new vYd('RESTART',0,null,'restart');PXd=new vYd('DISABLE_WARNING',1,null,'warn_equal_in_prog(0)');pYd=new vYd('PROBA_EPSILON',2,null,'proba_epsilon:=0;');UXd=new vYd('GGBIS_POLYNOMIAL',3,'ggbisPolynomial','ggbisPolynomial(a):= when (size(lname(a)) == 1, is_polynomial(a,lname(a)[0]),when (size(lname(a)) == 2, is_polynomial(a,lname(a)[0]) && is_polynomial(a,lname(a)[1]), ?))');$Xd=new vYd('GGB_IS_EQUALS',4,'ggb_is_equals',"ggb_is_equals(a):=when(a==equal||a=='%=',true,false)");EXd=new vYd('CHECK_DERIVATIVE',5,'check_derivative','check_derivative(a,b):=when(size(a)==1,a[0],flatten1([revlist(a),sort(remove(undef,map(a,r->when(isAlmostZero(evalf(subst(r,x=xcoord(b))-ycoord(b))),r,undef))))])[-1])');_Xd=new vYd('GGB_IS_GREATER_OR_GREATER_THAN_OR_EQUALS',6,'ggb_is_gt_or_ge_or_equals',"ggb_is_gt_or_ge_or_equals(a):=when(a=='>'||a=='>='||a==equal||a=='%=',true,false)");YXd=new vYd('GGB_FACTOR',7,'ggbfactor','ggbfactor(a, b, c, d):=[with_sqrt(c), factor(a, b), with_sqrt(d)][1]');XXd=new vYd('GGB_CFACTOR',8,'ggbcfactor','ggbcfactor(a, b, c, d):=[with_sqrt(c), cfactor(a, b), with_sqrt(d)][1]');cYd=new vYd('GGB_IS_VARIABLE',9,'ggb_is_variable','ggb_is_variable(a):=when(length(lvar(a))==1,lvar(a)[0],?)');bYd=new vYd('GGB_IS_NUMBER',10,'ggb_is_number','ggb_is_number(a):=[[ggbtype:=type(a)], when(ggbtype==DOM_INT||ggbtype==DOM_FLOAT||ggbtype==DOM_RAT,1,0)][1]');dYd=new vYd('GGB_LIST_DIFFERENCE',11,'ggbListDifference','ggbListDifference(x,y):=flatten1(map(x,e->when(member(e, y)==0,[e],[])))');WXd=new vYd('GGBZIPANS',12,'ggbzipans','ggbzipans(l):=begin local len0,res,sbl,xpr,k,j;xpr:=l[0];len0:=length(l[2]);res:={};for k from 4 to length(l)-1 step +2 do len0:=min(len0,length(l[k])); od;for k from 0 to len0-1 do sbl:={};for j from 2 to length(l)-1 step +2 do sbl:=append(sbl,l[j-1]=l[j][k]);od;res:=append(res,subst(xpr,sbl));od; res; end');VXd=new vYd('GGBMOD',13,'ggbmod',"ggbmod(a,b):=when(typeof(a)=='?',?,when(type(a)!=DOM_INT||type(b)!=DOM_INT,rem(a,b,when(length(lname(b))>0,lname(b)[0],x)),irem(a,b)))");aYd=new vYd('GGB_IS_LESS_THAN',14,'ggb_is_less_than',"ggb_is_less_than(a):=when(a=='<'||a=='<=',true,false)");rYd=new vYd('XCOORD',15,'xcoord',"xcoord(a):=when(type(evalf(a))==DOM_COMPLEX, real(a), when(type(a)==DOM_IDENT,xcoordsymb(a),when(a[0]=='pnt',when(is_3dpoint(a),a[1][0],real(a[1])),when(a[0]==equal,coeff(a[1]-a[2],x,1),a[0]))))");sYd=new vYd('YCOORD',16,'ycoord',"ycoord(a):=when(type(evalf(a))==DOM_COMPLEX, im(a), when(type(a)==DOM_IDENT,ycoordsymb(a),when(a[0]=='pnt',when(is_3dpoint(a),a[1][1],im(a[1])),when(a[0]==equal,coeff(a[1]-a[2],y,1),a[1]))))");tYd=new vYd('ZCOORD',17,'zcoord',"zcoord(a):=when(type(a)==DOM_IDENT,zcoordsymb(a),when(a[0]=='pnt',when(is_3dpoint(a),a[1][2],0),when(length(a)<3 && a[0] != equal,0,when(a[0]==equal,coeff(a[1]-a[2],z,1),a[2]))))");MXd=new vYd('DEG_ASIN',18,MEo,'asind(x):=normal(asin(x)/pi*180)*unicode0176u');LXd=new vYd('DEG_ACOS',19,NEo,'acosd(x):=normal(acos(x)/pi*180)*unicode0176u');NXd=new vYd('DEG_ATAN',20,OEo,'atand(x):=normal(atan(x)/pi*180)*unicode0176u');OXd=new vYd('DEG_ATAN2',21,PEo,'atan2d(y,x):=normal(arg(x+i*y)/pi*180)*unicode0176u');FXd=new vYd('COEFFICIENT_CONIC',22,'ggbcoeffconic','ggbcoeffconic(coeffsarg):={coeffs(coeffsarg,[x,y],[2,0]),coeffs(coeffsarg,[x,y],[0,2]),coeffs(coeffsarg,[x,y],[0,0]),coeffs(coeffsarg,[x,y],[1,1]),coeffs(coeffsarg,[x,y],[1,0]),coeffs(coeffsarg,[x,y],[0,1])}');GXd=new vYd('COEFFICIENT_QUADRIC',23,'ggbcoeffquadric','ggbcoeffquadric(coeffsarg):={coeffs(coeffsarg,[x,y,z],[2,0,0]),coeffs(coeffsarg,[x,y,z],[0,2,0]),coeffs(coeffsarg,[x,y,z],[0,0,2]),coeffs(coeffsarg,[x,y,z],[0,0,0]),coeffs(coeffsarg,[x,y,z],[1,1,0]),coeffs(coeffsarg,[x,y,z],[1,0,1]),coeffs(coeffsarg,[x,y,z],[0,1,1]),coeffs(coeffsarg,[x,y,z],[1,0,0]),coeffs(coeffsarg,[x,y,z],[0,1,0]),coeffs(coeffsarg,[x,y,z],[0,0,1])}');kYd=new vYd('IS_ZERO',24,'ggbIsZero',"ggbIsZero(ggbx):=when(ggbx==0 || simplify(texpand(ggbx))==0 || exp2pow(lin(pow2exp(ggbx)))==0,true,when(type(ggbx)=='DOM_LIST',max(flatten({ggbx,0}))==min(flatten({ggbx,0}))&&min(flatten({ggbx,0}))==0,when(ggbx[0]==equal,lhs(ggbx)==0&&rhs(ggbx)==0,ggbx[0]=='pnt' && ggbx[1] == ggbvect[0,0,0])))");iYd=new vYd('IS_ALMOST_ZERO',25,'isAlmostZero','isAlmostZero(a):=len(lname(a))==0 && evalf(a) < 10^-8');oYd=new vYd('PRIM_POLY',26,'primpoly','primpoly(x):=begin local pps,ii; if (x==[0]) return [0]; pps:=[]; for ii from 0 to size(x)-1 do pps[ii]:=primpart(x[ii],lvar(x[ii])); od return pps end');ZXd=new vYd('GGB_IN_STRING',27,'ggbinString','ggbinString(x,y):=begin local ret; ret := inString(x,y); if (ret == -1) return undef; else return ret; end');gYd=new vYd('INDEX_OF',28,'indexOf','indexOf(x, mylist):=begin local ii; for ii from 0 to length(mylist)-1 do if (mylist[ii] == x) begin print(ii); return ii; end; od; return undef; end');RXd=new vYd('FACTOR_SQR_FREE',29,'factorsqrfree',"factorsqrfree(p):=begin local pf,r,ii; pf:=factor(p); if (sommet(pf)!='*') begin if (sommet(pf)=='^') return op(pf)[0]; else begin if (sommet(pf)!=sommet(-x)) return pf; else return factorsqrfree(-pf); end; end; opPf:=op(pf); r:=1; for ii from 0 to size(opPf)-1 do r:=r*factorsqrfree(opPf[ii]); od return r end");SXd=new vYd('GEOM_ELIM',30,'geomElim','geomElim(polys,elimvars,precision):=begin local ee, ll, ff, gg, ii; ee:=eliminate(polys,revlist(elimvars)); /*print(ee);*/ ll:=lvar(ee); /*print(ll);*/ if (size(ee)>1) begin /*print(fsolve(ee,ll));*/ ff:=round(fsolve(ee,ll)*precision)/precision; /*print(ff);*/ gg:=1; for ii from 0 to size(ff)-1 do gg:=gg*(((ll[0]-ff[ii,0])^2+(ll[1]-ff[ii,1])^2)); /*print(gg);*/ od; ee:=[expand(lcm(denom(coeff(gg)))*gg)]; end; if (size(ee)==0) return 0; else return primpoly(ee)[0]; end;');mYd=new vYd('JACOBI_PREPARE',31,'jacobiPrepare','jacobiPrepare(polys,excludevars):=begin local ii, degs, pos, vars, linvar; vars:=lvar(polys); ii:=0; while (ii<size(polys)-1) do degs:=degree(polys[ii],vars); if (sum(degs)=1) begin pos:=find(1,degs); linvar:=vars[pos[0]]; if (!is_element(linvar,excludevars)) begin substval:=op(solve(polys[ii]=0,linvar)[0])[1]; polys:=remove(0,expand(subs(polys,[linvar],[substval]))); /*print(polys);*/ ii:=-1; end; end; ii:=ii+1; od; return polys; end');lYd=new vYd('JACOBI_DET',32,'jacobiDet','jacobiDet(polys,excludevars):=begin local J, ii, vars, s, j, k; vars:=lvar(polys); for ii from 0 to size(excludevars)-1 do vars:=remove(excludevars[ii], vars); od; s:=size(vars); J:=matrix(s,s,(j,k)->diff(polys[j],vars[k])); return det_minor(J); end');TXd=new vYd('GEOM_JACOBI_DET',33,'geomJacobiDet','geomJacobiDet(polys,excludevars):=begin local J; J:=jacobiPrepare(polys,excludevars); return jacobiDet(J,excludevars); end');QXd=new vYd('ENVELOPE_EQU',34,'envelopeEqu','envelopeEqu(polys,elimvars,precision,curvevarx,curvevary):=begin local D; D:=geomJacobiDet(polys,[curvevarx,curvevary]); polys:=append(polys,D); return locusEqu(polys,elimvars,precision,curvevarx,curvevary); end');nYd=new vYd('LOCUS_EQU',35,'locusEqu','locusEqu(polys,elimvars,precision,curvevarx,curvevary):=implicitCurveCoeffs(subst(geomElim(jacobiPrepare(polys,[curvevarx,curvevary]),elimvars,precision),[curvevarx=x,curvevary=y]))');IXd=new vYd('COEFF_MATRIX',36,'coeffMatrix','coeffMatrix(aa):=begin local bb, sx, sy, ii, jj, ee, cc, kk; bb:=coeffs(aa,x); sx:=size(bb); sy:=size(coeffs(aa,y)); cc:=[sx,sy]; for ii from sx-1 to 0 by -1 do dd:=coeff(bb[ii],y); sd:=size(dd); for jj from sd-1 to 0 by -1 do ee:=dd[jj]; cc:=append(cc,ee); od; for kk from sd to sy-1 do ee:=0; cc:=append(cc,ee); od; od; return cc; end');HXd=new vYd('COEFF_MATRICES',37,'coeffMatrices','coeffMatrices(aa):=begin local ff, bb, ccf, ll, aaf; ff:=factors(aa); ccf:=[size(ff)/2]; for ll from 0 to size(ff)-1 by 2 do aaf:=ff[ll]; bb:=coeffMatrix(aaf); ccf:=append(ccf,bb); od; return flatten(ccf); end');fYd=new vYd('IMPLICIT_CURVE_COEFFS',38,'implicitCurveCoeffs','implicitCurveCoeffs(aa):=begin local bb; bb:=factorsqrfree(aa); return [coeffMatrix(bb),coeffMatrices(bb)]; end');hYd=new vYd('IRRED',39,'irred','irred(p,x):=begin local f; f:=factors(primpart(p,x)); return (size(f)==2 && f[1]==1); end');DXd=new vYd('AFACTOR_ALG_NUM',40,'afactorAlgNum','afactorAlgNum(p):=begin local k,l,j,d,extdeg,xx,lv,px,lc,lv2,py,fy,lfy,yy,fydeg,deg,pm,pdeg; l:=lname(p); if (!irred(p,l[0])) return "Not irreducible"; if (size(l)<2) return p; d:=[]; for j in l do d:=append(d,degree(p,j)); od; extdeg:=lgcd(d); if (extdeg==1) return "Absolutely irreducible"; xx:=head(l); pdeg:=degree(p,xx); l:=tail(l); for j from 1 to 1000 do lv:=ranv(size(l),j); px:=primpart(subst(p,l,lv),xx); if (degree(px,xx)!=pdeg) continue; if (irred(px,xx)) break; od; lc:=lcoeff(px,xx); if (lc!=1) px:=primpart(subst(px,xx,xx/lc),xx); for j from j to 1000 do lv2:=ranv(size(l),extdeg+j); if (lv2==lv) continue; py:=primpart(subst(p,l,lv2),xx); if (degree(py,xx)!=pdeg || !irred(py,xx)) continue; fy:=factors(py,rootof(px)); fydeg:=map(fy,yy->degree(yy,xx)); deg:=gcd(fydeg); deg:=d[0]/deg; if (deg==extdeg && degree(px)==extdeg) break; extdeg:=gcd(deg,extdeg); if (extdeg==1) return "Absolutely irreducible"; if (deg>extdeg) continue; for k from 0 to size(fydeg)-1 do if (fydeg[k]*extdeg==d[0]) break; od; if (k==size(fydeg)) continue; lfy:=coeff(fy[k],xx); for k from 0 to size(lfy)-1 do pm:=pmin(lfy[k]); if (degree(pm)==extdeg) begin px:=pm; break; end; od; od; return px; end');CXd=new vYd('ABSFACT',41,'absfact','absfact(p):=begin local algnum; algnum:=afactorAlgNum(p); /*print(algnum,type(algnum));*/ if (type(algnum)==DOM_LIST || type(algnum)==DOM_SYMBOLIC) return factor(p,rootof(algnum)); else return p; end');eYd=new vYd('GGB_ROUND',42,'ggbround','ggbround(x):=when(evalf(x)==?||evalf(x)=={?},?,when(type(evalf(x))==DOM_LIST,seq(ggbround(x[j]),j,0,length(x)-1),when(type(evalf(x))==DOM_COMPLEX,ggbround(real(x))+i*ggbround(im(x)),when(x<0,when(type(x)==DOM_LIST&&length(x)==2,-round(-x[0], x[1]),-round(-x)),round(x)))))');JXd=new vYd('COS_2PI_OVER_N_MINPOLY',43,'cos2piOverNMinpoly','cos2piOverNMinpoly(n):=begin local j, p, q, r; p:=simplify((tchebyshev1(n)-1)/(x-1)); for j from 1 to n/2 do q:=tchebyshev1(j)-1; r:=gcd(p,q); p:=simplify(p/r); od; return factorsqrfree(primpart(p)); end');jYd=new vYd('IS_EQUAL_EQUATIONS',44,'ggbIsEqualEquations','ggbIsEqualEquations(eq1,eq2):=when(ggbIsZero(eq1)&&ggbIsZero(eq2),true,when(ggbIsZero(eq1)||ggbIsZero(eq2),false,type(normal(equal2diff(eq1)/equal2diff(eq2)))!=DOM_SYMBOLIC))')}
